func TestCreateCertificateRequest(t *testing.T) {
	r := rand.Reader
	priv, err := rsa.GenerateKey(r, 1024)
	if err != nil {
		t.Fatal(err)
	}

	template := CertificateRequest{
		CertificateRequest: x509.CertificateRequest{
